#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 int minMaxDifference(int num){
  string s=to_string(num),hi=s,lo=s;
  char from='9';for(char c:s)if(c!='9'){from=c;break;}
  for(char &c:hi)if(c==from)c='9';
  for(char &c:lo)if(c==s[0])c='0';
  return stoi(hi)-stoi(lo);
 }
};
